/**
 * Malha das 27 unidades da federação, em caminhos SVG já projetados.
 *
 * Fonte: API de malhas territoriais do IBGE (malhas simplificadas, divisão por
 * UF), obtida em 22/09/2026 e incorporada aqui. É geometria pública; fica no
 * código porque o mapa não pode depender de rede para desenhar — e porque
 * baixar 27 contornos a cada abertura da tela seria desperdício.
 *
 *   https://servicodados.ibge.gov.br/api/docs/malhas?versao=3
 *
 * ⚠️ Os caminhos estão no sistema de coordenadas do `viewBox` abaixo. Não
 * reescalar os números: mudar o viewBox é o jeito de mudar o tamanho.
 *
 * `rotuloX`/`rotuloY` é onde a sigla da UF cabe sem cair fora do contorno —
 * medido no desenho, não calculado por centroide (o centroide do Amazonas,
 * por exemplo, cai perto da divisa e a sigla invade o Pará).
 */

/** Sistema de coordenadas dos caminhos. */
export const VIEWBOX_DO_BRASIL = "0 0 730 680";

export const REGIOES = ["Norte", "Nordeste", "Centro-Oeste", "Sudeste", "Sul"] as const;
export type Regiao = (typeof REGIOES)[number];

export type UnidadeFederativa = Readonly<{
  /** Código do IBGE. É a chave estável; a sigla é só rótulo. */
  codigo: number;
  sigla: string;
  nome: string;
  regiao: Regiao;
  /**
   * Retângulo que envolve o contorno, no mesmo sistema. É o que o mapa usa
   * para ampliar a UF: pré-calculado aqui porque `getBBox()` só existe no
   * navegador, e o mapa precisa sair certo já no render do servidor.
   */
  caixa: Readonly<{ x: number; y: number; largura: number; altura: number }>;
  /** Caminho SVG do contorno, no sistema de `VIEWBOX_DO_BRASIL`. */
  contorno: string;
  rotuloX: number;
  rotuloY: number;
}>;

