/** Busca por sigla. Devolve indefinido para sigla que não existe. */
export function ufPorSigla(sigla: string | null | undefined): UnidadeFederativa | undefined {
  if (!sigla) return undefined;
  const alvo = sigla.trim().toUpperCase();
  return UNIDADES_FEDERATIVAS.find((uf) => uf.sigla === alvo);
}

/** Siglas de uma região, em ordem alfabética. */
export function siglasDaRegiao(regiao: Regiao): readonly string[] {
  return UNIDADES_FEDERATIVAS.filter((uf) => uf.regiao === regiao).map((uf) => uf.sigla);
}
